using namespace std;

int main() {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;
    vector<long long> a(n);
    for (auto &x : a) scanf("%lld", &x);
    const long long INF = (long long)1e18;
    vector<long long> dp(n + 1, INF);
    dp[0] = 0;
    for (int groups = 1; groups <= k; groups++) {
        vector<long long> nxt(n + 1, INF);
        for (int end = groups; end <= n; end++) {
            long long maximum = 0;
            // The last segment is a[start..end-1]; extend it to the left.
            for (int start = end - 1; start >= groups - 1; start--) {
                maximum = max(maximum, a[start]);
                if (dp[start] < INF) nxt[end] = min(nxt[end], dp[start] + maximum);
            }
        }
        dp.swap(nxt);
    }
    printf("%lld\n", dp[n]);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), k = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        final long INF = (long) 1e18;
        long[] dp = new long[n + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int groups = 1; groups <= k; groups++) {
            long[] nxt = new long[n + 1];
            Arrays.fill(nxt, INF);
            for (int end = groups; end <= n; end++) {
                long maximum = 0;
                // The last segment is a[start..end-1]; extend it to the left.
                for (int start = end - 1; start >= groups - 1; start--) {
                    maximum = Math.max(maximum, a[start]);
                    if (dp[start] < INF) nxt[end] = Math.min(nxt[end], dp[start] + maximum);
                }
            }
            dp = nxt;
        }
        System.out.println(dp[n]);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := int(nextInt()), int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	const INF = int64(1e18)
	dp := make([]int64, n+1)
	for i := range dp {
		dp[i] = INF
	}
	dp[0] = 0
	for groups := 1; groups <= k; groups++ {
		nxt := make([]int64, n+1)
		for i := range nxt {
			nxt[i] = INF
		}
		for end := groups; end <= n; end++ {
			var maximum int64
			// The last segment is a[start..end-1]; extend it to the left.
			for start := end - 1; start >= groups-1; start-- {
				maximum = max(maximum, a[start])
				if dp[start] < INF {
					nxt[end] = min(nxt[end], dp[start]+maximum)
				}
			}
		}
		dp = nxt
	}
	fmt.Println(dp[n])
}
